require"active_support";module Rails;module Command;module Behavior
extend ActiveSupport::Concern;class_methods do def no_color!;Thor::Base.shell=Thor::Shell::Basic;end;def subclasses;@subclasses||=[];end;private;def print_list(base,namespaces)return if namespaces.empty?;puts"#{base.camelize}:";namespaces.each do |namespace|puts("  #{namespace}");end;puts;end;def lookup(namespaces)paths=namespaces_to_paths(namespaces);paths.each do |raw_path|lookup_paths.each do |base|path="#{base}/#{raw_path}_#{command_type}";begin require path;return ;rescue LoadError=>e;raise unless /#{Regexp.escape(path)}$/.match?(e.message);rescue Exception=>e;warn"[WARNING] Could not load #{command_type} #{path.inspect}. Error: #{e.message}.\n#{e.backtrace.join("\n")}";end;end;end;end;def lookup!;$LOAD_PATH.each do |base|Dir[File.join(base,*file_lookup_paths)].each do |path|path=path.delete_prefix("#{base}/");require path;rescue Exception;end;end;end;def namespaces_to_paths(namespaces)paths=[];namespaces.each do |namespace|pieces=namespace.split(":");path=pieces.join("/");paths<<"#{path}/#{pieces.last}";paths<<path;end;paths.uniq!;paths;end;end;end;end;end
